import{_ as a}from"./chunks/popup-translate.Bz3dSJPd.js";import{_ as e,o,c as n,a2 as r}from"./chunks/framework.CfwCq2QB.js";const l="/dev-go-docs/shots/0.2.3/en/light/options-translate.png",f=JSON.parse('{"title":"Full-page bilingual translation","description":"","frontmatter":{},"headers":[],"relativePath":"en/features/page-translate.md","filePath":"en/features/page-translate.md"}'),s={name:"en/features/page-translate.md"};function i(d,t,h,g,p,u){return o(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="full-page-bilingual-translation" tabindex="-1">Full-page bilingual translation <a class="header-anchor" href="#full-page-bilingual-translation" aria-label="Permalink to &quot;Full-page bilingual translation&quot;">​</a></h1><p>In one line: translations are inserted after each original paragraph, load as you scroll, and one more click restores the original. Shadow DOM / Web Components pages are supported.</p><h2 id="where-to-start" tabindex="-1">Where to start <a class="header-anchor" href="#where-to-start" aria-label="Permalink to &quot;Where to start&quot;">​</a></h2><ul><li><strong>Popup</strong>: <code>Alt+1</code> → Translate page → &quot;Translate this page / Show original&quot;</li><li><strong>Context menu</strong>: right-click an empty spot → &quot;Translate this page (click again to restore the original)&quot;</li><li><strong>Floating dock</strong>: hover the right edge → &quot;Translate this page / Show original&quot;</li><li><strong>Shortcut</strong>: &quot;Toggle page translation&quot; has no default key — bind one at <code>chrome://extensions/shortcuts</code></li><li><strong>Automatic</strong>: add your go-to sites to &quot;Always translate this site&quot; and they translate on open</li></ul><img src="'+a+'" alt="The popup&#39;s Translate page" style="width:60%;display:block;margin-left:auto;margin-right:auto;"><p><em>The popup&#39;s Translate page: engine, target language, and &quot;Always translate this site&quot;.</em></p><h2 id="translation-engines" tabindex="-1">Translation engines <a class="header-anchor" href="#translation-engines" aria-label="Permalink to &quot;Translation engines&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Engine</th><th>Notes</th></tr></thead><tbody><tr><td>Microsoft · no proxy</td><td>Default. Free, reachable without a proxy</td></tr><tr><td>Google</td><td>Great quality, needs a proxy</td></tr><tr><td>AI model</td><td>Translate with your own LLM for control over tone and terminology; configure a translation model under <a href="/dev-go-docs/en/settings/models.html">AI models</a></td></tr></tbody></table><p>Target language defaults to &quot;Auto (Chinese ⇄ English)&quot;: Chinese pages are translated to English, everything else to Simplified Chinese. You can also fix it to any of 17 languages.</p><h2 id="display" tabindex="-1">Display <a class="header-anchor" href="#display" aria-label="Permalink to &quot;Display&quot;">​</a></h2><p>Under Settings → Translation → Page translation:</p><ul><li><strong>Bilingual</strong> (default): translations follow each original paragraph</li><li><strong>Translation only</strong>: hide the original for a cleaner read</li><li><strong>Underline translations</strong>: dotted underline to tell translations apart at a glance</li></ul><h2 id="hover-translation" tabindex="-1">Hover translation <a class="header-anchor" href="#hover-translation" aria-label="Permalink to &quot;Hover translation&quot;">​</a></h2><p>Don&#39;t want the whole page translated? Enable <strong>hover translation</strong> under Settings → Translation and translate one paragraph at a time:</p><table tabindex="0"><thead><tr><th>Mode</th><th>How it works</th></tr></thead><tbody><tr><td>Press <code>Alt</code> / <code>Ctrl</code> / <code>Shift</code></td><td>Point at a paragraph, press the modifier once to translate, again to restore (default Alt; ⌥ on macOS)</td></tr><tr><td>Auto after hovering</td><td>Hover over a paragraph briefly to translate it</td></tr></tbody></table><h2 id="always-translate-this-site" tabindex="-1">Always translate this site <a class="header-anchor" href="#always-translate-this-site" aria-label="Permalink to &quot;Always translate this site&quot;">​</a></h2><p>Add sites you read often — <code>developer.mozilla.org</code>, for example — and they translate automatically on open. You can also toggle the current site from the popup&#39;s Translate page.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Browser built-in pages (<code>chrome://</code> URLs) and the extension store can&#39;t be translated; on normal pages, refresh once if translation doesn&#39;t kick in right after install</li><li>Long pages translate on demand: failed paragraphs get a ↻ to retry individually</li><li>With an AI model as the engine, prefer a fast model without deep thinking (glm-4-flash, qwen-turbo) — full-page translation stays responsive</li></ul><img src="'+l+'" alt="Translation settings"><p><em>Settings → Translation: display, underline, hover translation, and &quot;always translate&quot; sites.</em></p>',21)])])}const y=e(s,[["render",i]]);export{f as __pageData,y as default};
